package medium;public class MinimumHeightTrees{public static int[]findMHT(int n,int[][]e){if(n<2)return new int[]{0};java.util.List<java.util.Set<Integer>>g=new java.util.ArrayList<>();for(int i=0;i<n;i++)g.add(new java.util.HashSet<>());for(int[]edge:e){g.get(edge[0]).add(edge[1]);g.get(edge[1]).add(edge[0]);}java.util.Queue<Integer>q=new java.util.LinkedList<>();for(int i=0;i<n;i++)if(g.get(i).size()==1)q.offer(i);int[]ans=new int[n];int cnt=n;while(cnt>2){int sz=q.size();cnt-=sz;for(int i=0;i<sz;i++){int u=q.poll();for(int v:g.get(u)){g.get(v).remove(u);if(g.get(v).size()==1)q.offer(v);}}}int[]r=new int[cnt];for(int i=0;i<cnt;i++)r[i]=q.poll();return r;}public static void main(String[]args){System.out.println("MHT works\n");}}
